CREATE TABLE rt_suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(80) NOT NULL UNIQUE, name varchar(255) NOT NULL, status varchar(24) NOT NULL DEFAULT 'pending', adapter_code varchar(80), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rt_supplier_entitlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES rt_suppliers(id) ON DELETE RESTRICT, channel varchar(8) NOT NULL CHECK(channel IN ('b2b','b2c')), service_type varchar(32) NOT NULL, product_scope varchar(160), rate_scope varchar(160), is_allowed boolean NOT NULL DEFAULT false, is_verified boolean NOT NULL DEFAULT false, valid_from timestamptz NOT NULL, valid_to timestamptz, evidence_file_id uuid REFERENCES rt_files(id) ON DELETE RESTRICT, approved_by bigint REFERENCES users(id) ON DELETE RESTRICT, version integer NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), CHECK(valid_to IS NULL OR valid_to>valid_from));
CREATE INDEX rt_entitlement_lookup_idx ON rt_supplier_entitlements(supplier_id,channel,service_type,is_allowed,is_verified,valid_from);
CREATE TABLE rt_supplier_capabilities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES rt_suppliers(id) ON DELETE RESTRICT, service_type varchar(32) NOT NULL, capability varchar(64) NOT NULL, support_status varchar(24) NOT NULL DEFAULT 'unverified', evidence text, verified_at timestamptz, UNIQUE(supplier_id,service_type,capability));
CREATE TABLE rt_currencies (code char(3) PRIMARY KEY, name_en varchar(80) NOT NULL, name_ar varchar(80), minor_units smallint NOT NULL CHECK(minor_units BETWEEN 0 AND 6), is_enabled boolean NOT NULL DEFAULT false);
INSERT INTO rt_currencies(code,name_en,name_ar,minor_units,is_enabled) VALUES ('USD','US Dollar','دولار أمريكي',2,true),('SAR','Saudi Riyal','ريال سعودي',2,true),('EGP','Egyptian Pound','جنيه مصري',2,true);
CREATE TABLE rt_fx_rates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), base_currency char(3) NOT NULL REFERENCES rt_currencies(code), quote_currency char(3) NOT NULL REFERENCES rt_currencies(code), rate_type varchar(16) NOT NULL CHECK(rate_type IN ('reference','commercial')), rate numeric(24,12) NOT NULL CHECK(rate>0), source varchar(120) NOT NULL, policy_version varchar(64), channel varchar(8), company_id uuid REFERENCES rt_companies(id) ON DELETE RESTRICT, effective_at timestamptz NOT NULL, expires_at timestamptz, recorded_at timestamptz NOT NULL DEFAULT now(), CHECK(base_currency<>quote_currency), CHECK(expires_at IS NULL OR expires_at>effective_at));
CREATE INDEX rt_fx_rates_lookup_idx ON rt_fx_rates(base_currency,quote_currency,rate_type,effective_at DESC);
CREATE TABLE rt_pricing_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(80) NOT NULL, version integer NOT NULL CHECK(version>0), channel varchar(8), company_id uuid REFERENCES rt_companies(id) ON DELETE RESTRICT, status varchar(24) NOT NULL DEFAULT 'draft', effective_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(code,version));
CREATE TABLE rt_pricing_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), policy_id uuid NOT NULL REFERENCES rt_pricing_policies(id) ON DELETE RESTRICT, rule_kind varchar(32) NOT NULL, calculation_type varchar(32) NOT NULL, value numeric(20,6) NOT NULL, priority integer NOT NULL DEFAULT 0, service_type varchar(32), supplier_id uuid REFERENCES rt_suppliers(id) ON DELETE RESTRICT);
